SELECT json_build_object('player_id',p.user_id,'profile_version',p.version,'selected_class',p.selected_class,'gold',w.gold,'potions',c.health_potion_count,'total_shop_rows',(SELECT count(*) FROM shop_purchases WHERE player_id=p.user_id),'total_price',(SELECT sum(price_gold) FROM shop_purchases WHERE player_id=p.user_id),'lost_rows',(SELECT count(*) FROM shop_purchases WHERE player_id=p.user_id AND request_id='godot-740f5dc0c9d65bca2b3a5a83307c0934'),'lost_quantity',(SELECT sum(quantity) FROM shop_purchases WHERE player_id=p.user_id AND request_id='godot-740f5dc0c9d65bca2b3a5a83307c0934'),'lost_price',(SELECT sum(price_gold) FROM shop_purchases WHERE player_id=p.user_id AND request_id='godot-740f5dc0c9d65bca2b3a5a83307c0934'),'lost_ledger_rows',(SELECT count(*) FROM economy_ledger WHERE player_id=p.user_id AND request_id='godot-740f5dc0c9d65bca2b3a5a83307c0934' AND currency='Gold'),'lost_ledger_delta',(SELECT sum(delta) FROM economy_ledger WHERE player_id=p.user_id AND request_id='godot-740f5dc0c9d65bca2b3a5a83307c0934' AND currency='Gold'),'overlap_rows',(SELECT count(*) FROM shop_purchases WHERE player_id=p.user_id AND request_id='godot-9829866118b259a88e36870f417856db'),'other_gold',(SELECT gold FROM player_wallets WHERE player_id='01a12db6-fc2d-7f36-bac4-a85a2033603d'),'other_potions',(SELECT health_potion_count FROM player_consumables WHERE player_id='01a12db6-fc2d-7f36-bac4-a85a2033603d')) FROM players p JOIN player_wallets w ON w.player_id=p.user_id JOIN player_consumables c ON c.player_id=p.user_id WHERE p.user_id='01a12db6-fabf-7f19-bde3-dcdc2798c167'
